// SetFileinfos removes all previously related items of the
// course replacing them completely with the passed
// in related items, optionally inserting them as new records.
// Sets o.R.Course's Fileinfos accordingly.
// Replaces o.R.Fileinfos with related.
// Sets related.R.Course's Fileinfos accordingly.
func (o *Course) SetFileinfos(exec boil.Executor, insert bool, related ...*Fileinfo) error {
	query := "update \"fileinfo\" set \"course_id\" = null where \"course_id\" = $1"
	values := []any{o.ID}
	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, query)
		fmt.Fprintln(boil.DebugWriter, values)
	}
	_, err := exec.Exec(query, values...)
	if err != nil {
		return errors.Wrap(err, "failed to remove relationships before set")
	}

	if o.R != nil {
		for _, rel := range o.R.Fileinfos {
			queries.SetScanner(&rel.CourseID, nil)
			if rel.R == nil {
				continue
			}

			rel.R.Course = nil
		}
		o.R.Fileinfos = nil
	}

	return o.AddFileinfos(exec, insert, related...)
}

// RemoveFileinfos relationships from objects passed in.
// Removes related items from R.Fileinfos (uses pointer comparison, removal does not keep order)
// Sets related.R.Course.
func (o *Course) RemoveFileinfos(exec boil.Executor, related ...*Fileinfo) error {
	if len(related) == 0 {
		return nil
	}

	var err error
	for _, rel := range related {
		queries.SetScanner(&rel.CourseID, nil)
		if rel.R != nil {
			rel.R.Course = nil
		}
		if _, err = rel.Update(exec, boil.Whitelist("course_id")); err != nil {
			return err
		}
	}
	if o.R == nil {
		return nil
	}

	for _, rel := range related {
		for i, ri := range o.R.Fileinfos {
			if rel != ri {
				continue
			}

			ln := len(o.R.Fileinfos)
			if ln > 1 && i < ln-1 {
				o.R.Fileinfos[i] = o.R.Fileinfos[ln-1]
			}
			o.R.Fileinfos = o.R.Fileinfos[:ln-1]
			break
		}
	}

	return nil
}

